import{B as e,Q as t,s as n,z as r}from"./chunks/framework.3ZETo7pw.js";var i=JSON.parse(`{"title":"ADR 0002: Modular Monolith vs Decoupled SPA (Inertia.js + React)","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/decisions/0002-modular-monolith-inertia-react.md","filePath":"architecture/decisions/0002-modular-monolith-inertia-react.md"}`),a={name:`architecture/decisions/0002-modular-monolith-inertia-react.md`};function o(n,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[e(`<h1 id="adr-0002-modular-monolith-vs-decoupled-spa-inertia-js-react" tabindex="-1">ADR 0002: Modular Monolith vs Decoupled SPA (Inertia.js + React) <a class="header-anchor" href="#adr-0002-modular-monolith-vs-decoupled-spa-inertia-js-react" aria-label="Permalink to &quot;ADR 0002: Modular Monolith vs Decoupled SPA (Inertia.js + React)&quot;">​</a></h1><p><strong>Status:</strong> Accepted <strong>Date:</strong> 2024-05-25</p><h2 id="_1-context-and-problem" tabindex="-1">1. Context and Problem <a class="header-anchor" href="#_1-context-and-problem" aria-label="Permalink to &quot;1. Context and Problem&quot;">​</a></h2><p>For the TechyNews platform, we needed to select a frontend and backend architecture that allows rapid feature development, excellent SEO (crucial for a news platform), and a highly interactive user experience.</p><p>The standard industry approach is often to build a decoupled REST or GraphQL API (Backend) and a completely separate Next.js or Nuxt.js application (Frontend). However, maintaining two separate repositories, duplicated state logic, and complex CORS/Auth configurations slows down development for small-to-medium teams.</p><h2 id="_2-considered-options" tabindex="-1">2. Considered Options <a class="header-anchor" href="#_2-considered-options" aria-label="Permalink to &quot;2. Considered Options&quot;">​</a></h2><ul><li><strong>Option A: Decoupled Architecture (Laravel API + Next.js Frontend).</strong></li><li><strong>Option B: Traditional Server-Side Rendering (Laravel Blade).</strong></li><li><strong>Option C: Modern Monolith (Laravel + React + Inertia.js).</strong></li></ul><h2 id="_3-decision" tabindex="-1">3. Decision <a class="header-anchor" href="#_3-decision" aria-label="Permalink to &quot;3. Decision&quot;">​</a></h2><p>We selected <strong>Option C: Modern Monolith using Laravel and Inertia.js with React 18.</strong></p><p>Inertia.js acts as a &quot;glue&quot; layer that allows us to build a fully client-side rendered, single-page application (SPA) using React, without the complexity of building an API. Laravel handles the routing, database (MySQL/Eloquent), and controllers, returning Inertia responses instead of JSON or HTML views.</p><h2 id="_4-consequences" tabindex="-1">4. Consequences <a class="header-anchor" href="#_4-consequences" aria-label="Permalink to &quot;4. Consequences&quot;">​</a></h2><h3 id="positive" tabindex="-1">Positive: <a class="header-anchor" href="#positive" aria-label="Permalink to &quot;Positive:&quot;">​</a></h3><ul><li><strong>Development Velocity:</strong> No need to write separate REST API endpoints, manage state with Redux, or handle complex JWT authentication. We use standard Laravel session authentication out of the box.</li><li><strong>Single Codebase:</strong> Frontend and backend live in the same repository (<code>techy-laravel</code>), simplifying CI/CD pipelines (rsync/SSH to cPanel) and local environments.</li><li><strong>Performance:</strong> Users get the snappy, no-page-reload experience of a React SPA, which is enhanced by Framer Motion for smooth UI transitions.</li></ul><h3 id="negative-trade-offs" tabindex="-1">Negative / Trade-offs: <a class="header-anchor" href="#negative-trade-offs" aria-label="Permalink to &quot;Negative / Trade-offs:&quot;">​</a></h3><ul><li><strong>Mobile App Future-Proofing:</strong> Since we aren&#39;t building a dedicated REST API, if we ever decide to build a native iOS/Android app in the future, we will need to expose a separate API layer at that time. (Mitigation: Laravel&#39;s modularity makes adding an API layer straightforward when needed).</li><li><strong>Bundle Size:</strong> Initial page loads carry the React and Inertia JavaScript bundles, which are slightly heavier than static HTML, though Vite handles code-splitting efficiently.</li></ul>`,15)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};